"$PYTHON" -m hemispheres.synth.build --name world-b --index 1 --seed 0 --persons 10000 --companies 800 --universities 60 --cities 200 --countries 25 --zipf 0.8 --max-hops 3 --heldout-frac 0.2 --id-test-frac 0.1 --edits 1,100,1000
